/*
 * Linux-only attempt custodian. It is intentionally a single, dependency-free C file: the Node
 * shim API writes a bounded binary spawn specification, this process owns child reaping, and no
 * JSON parser or downloaded native dependency participates in custody.
 */
#define _GNU_SOURCE
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/prctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#define MAGIC "JNSP1"
#define MAX_ITEMS 512
#define MAX_BYTES (1024 * 1024)
typedef struct { char *attempt, *nonce, *meta, *secrets, *cwd, *out, *err; char **argv, **env; int argc, envc; uint32_t heartbeat; } spec_t;
static volatile sig_atomic_t wake_cancel = 0;
static void wake(int sig) { (void)sig; wake_cancel = 1; }
static uint32_t u32(const unsigned char **p, const unsigned char *end) { if (*p + 4 > end) return UINT32_MAX; uint32_t n = (uint32_t)(*p)[0] | ((uint32_t)(*p)[1] << 8) | ((uint32_t)(*p)[2] << 16) | ((uint32_t)(*p)[3] << 24); *p += 4; return n; }
static char *string(const unsigned char **p, const unsigned char *end) { uint32_t n = u32(p,end); if (n == UINT32_MAX || n > MAX_BYTES || *p + n > end) return NULL; char *r = calloc((size_t)n+1,1); if (!r) return NULL; memcpy(r,*p,n); *p += n; return r; }
static void die(const char *m) { dprintf(2,"jinn-attempt-shim: %s\n",m); _exit(78); }
static int parse(const char *path, spec_t *s) {
  int fd=open(path,O_RDONLY); struct stat st; if(fd<0||fstat(fd,&st)<0||st.st_size<5||st.st_size>MAX_BYTES){if(fd>=0)close(fd);return -1;} unsigned char *b=malloc((size_t)st.st_size); if(!b)return -1; size_t off=0; while(off<(size_t)st.st_size){ssize_t n=read(fd,b+off,(size_t)st.st_size-off);if(n<=0){free(b);close(fd);return -1;}off+=(size_t)n;}close(fd); const unsigned char *p=b,*e=b+st.st_size; if(memcmp(p,MAGIC,5)){free(b);return -1;}p+=5;
  s->attempt=string(&p,e);s->nonce=string(&p,e);s->meta=string(&p,e);s->secrets=string(&p,e);s->cwd=string(&p,e);s->out=string(&p,e);s->err=string(&p,e);s->heartbeat=u32(&p,e); uint32_t ac=u32(&p,e); if(!s->attempt||!s->nonce||!s->meta||!s->secrets||!s->cwd||ac==UINT32_MAX||ac==0||ac>MAX_ITEMS){free(b);return -1;} s->argv=calloc(ac+1,sizeof(char*));s->argc=(int)ac; for(uint32_t i=0;i<ac;i++)if(!(s->argv[i]=string(&p,e))){free(b);return -1;} uint32_t ec=u32(&p,e);if(ec==UINT32_MAX||ec>MAX_ITEMS){free(b);return -1;}s->env=calloc(ec+4,sizeof(char*));s->envc=(int)ec;for(uint32_t i=0;i<ec;i++)if(!(s->env[i]=string(&p,e))){free(b);return -1;} if(p!=e){free(b);return -1;}free(b);return 0;
}
static void free_spec(spec_t*s){for(int i=0;i<s->argc;i++)free(s->argv[i]);for(int i=0;i<s->envc;i++)free(s->env[i]);free(s->argv);free(s->env);free(s->attempt);free(s->nonce);free(s->meta);free(s->secrets);free(s->cwd);free(s->out);free(s->err);}
static void fswrite(const char *path,const char *bytes){char tmp[4096];snprintf(tmp,sizeof(tmp),"%s.tmp-%ld",path,(long)getpid());int fd=open(tmp,O_WRONLY|O_CREAT|O_EXCL,0600);if(fd<0)die("cannot create atomic temporary file");size_t l=strlen(bytes);if(write(fd,bytes,l)!=(ssize_t)l||fsync(fd)<0){close(fd);unlink(tmp);die("cannot fsync durable record");}close(fd);if(rename(tmp,path)<0)die("cannot rename durable record");char dir[4096];snprintf(dir,sizeof(dir),"%s",path);char *slash=strrchr(dir,'/');if(slash){*slash=0;fd=open(dir,O_RDONLY|O_DIRECTORY);if(fd<0||fsync(fd)<0){if(fd>=0)close(fd);die("cannot fsync durable directory");}close(fd);}}
static long start_time(pid_t pid){char path[64],buf[4096];snprintf(path,sizeof(path),"/proc/%ld/stat",(long)pid);int fd=open(path,O_RDONLY);if(fd<0)return -1;ssize_t n=read(fd,buf,sizeof(buf)-1);close(fd);if(n<=0)return -1;buf[n]=0;char *r=strrchr(buf,')');if(!r)return -1;char *q=r+2;for(int i=3;i<22;i++){q=strchr(q,' ');if(!q)return -1;q++;}return strtol(q,NULL,10);}
static int group_members(pid_t pgid,int include_leader){DIR*d=opendir("/proc");if(!d)return 0;int count=0;struct dirent*x;while((x=readdir(d))){char *end=NULL;long p=strtol(x->d_name,&end,10);if(!end||*end)continue;char path[64],buf[512];snprintf(path,sizeof(path),"/proc/%ld/stat",p);int fd=open(path,O_RDONLY);if(fd<0)continue;ssize_t n=read(fd,buf,sizeof(buf)-1);close(fd);if(n<=0)continue;buf[n]=0;char*r=strrchr(buf,')');if(!r)continue;char state=0;long parent=0,pgrp=0;if(sscanf(r+2,"%c %ld %ld",&state,&parent,&pgrp)!=3)continue;if(pgrp==pgid&&(include_leader||p!=pgid))count++;}closedir(d);return count;}
static void signal_group(pid_t pgid,int sig){if(kill(-pgid,sig)<0&&errno!=ESRCH){} }
static void sleep_ms(uint32_t ms){struct timespec t={.tv_sec=ms/1000,.tv_nsec=(long)(ms%1000)*1000000L};nanosleep(&t,NULL);}
static const char *signal_name(int signal){switch(signal){case SIGTERM:return "SIGTERM";case SIGKILL:return "SIGKILL";case SIGINT:return "SIGINT";case SIGHUP:return "SIGHUP";default:return strsignal(signal);}}
static int json_value(const char *b,const char *key,char*out,size_t cap){char needle[128];snprintf(needle,sizeof(needle),"\"%s\":\"",key);char*p=strstr((char*)b,needle);if(!p)return 0;p+=strlen(needle);char*q=strchr(p,'\"');if(!q||(size_t)(q-p)>=cap)return 0;memcpy(out,p,(size_t)(q-p));out[q-p]=0;return 1;}
static long json_number(const char*b,const char*key){char needle[128];snprintf(needle,sizeof(needle),"\"%s\":",key);char*p=strstr((char*)b,needle);return p?strtol(p+strlen(needle),NULL,10):-1;}
static int read_cancel(spec_t*s,uint32_t*g,uint32_t*k){char path[4096],buf[1024],n[512];snprintf(path,sizeof(path),"%s/cancellation-command.json",s->meta);int fd=open(path,O_RDONLY);if(fd<0)return 0;ssize_t z=read(fd,buf,sizeof(buf)-1);close(fd);if(z<=0)return 0;buf[z]=0;if(!json_value(buf,"nonce",n,sizeof(n))||strcmp(n,s->nonce))return 0;long a=json_number(buf,"graceMs"),b=json_number(buf,"killPollCeilingMs");if(a<0||b<0||a>INT32_MAX||b>INT32_MAX)return 0;*g=(uint32_t)a;*k=(uint32_t)b;return 1;}
static void heartbeat(spec_t*s){char p[4096],b[256];struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);snprintf(p,sizeof(p),"%s/heartbeat",s->meta);snprintf(b,sizeof(b),"{\"monotonicMs\":\"%lld\",\"wallClock\":\"%lld\"}",(long long)t.tv_sec*1000+t.tv_nsec/1000000,(long long)time(NULL));fswrite(p,b);}
static void cgroup_bind(pid_t pid,spec_t*s,char*out,size_t cap){char base[]="/sys/fs/cgroup",name[256],path[512],procs[600];snprintf(out,cap,"residual");if(access(base,W_OK))return;snprintf(name,sizeof(name),"jinn-%ld-%s",(long)pid,s->nonce);for(char*p=name;*p;p++)if(!((*p>='a'&&*p<='z')||(*p>='A'&&*p<='Z')||(*p>='0'&&*p<='9')||*p=='-'||*p=='_'))*p='_';snprintf(path,sizeof(path),"%s/%s",base,name);if(mkdir(path,0755)<0)return;snprintf(procs,sizeof(procs),"%s/cgroup.procs",path);int fd=open(procs,O_WRONLY);if(fd<0){rmdir(path);return;}char n[64];int l=snprintf(n,sizeof(n),"%ld",(long)pid);if(write(fd,n,(size_t)l)!=(ssize_t)l){close(fd);rmdir(path);return;}close(fd);snprintf(out,cap,"delegated");}
int main(int argc,char**argv){if(argc==2&&!strcmp(argv[1],"--probe")){int ok=prctl(PR_SET_CHILD_SUBREAPER,1,0,0,0)==0;printf("{\"ready\":%s,\"subreaper\":%s}\n",ok?"true":"false",ok?"true":"false");return ok?0:1;}if(argc!=2)die("missing binary spawn spec");spec_t s={0};if(parse(argv[1],&s))die("invalid binary spawn spec");if(prctl(PR_SET_CHILD_SUBREAPER,1,0,0,0)<0)die("PR_SET_CHILD_SUBREAPER unavailable");struct sigaction sa={0};sa.sa_handler=wake;sigaction(SIGUSR1,&sa,NULL);sigaction(SIGTERM,&sa,NULL);sigaction(SIGINT,&sa,NULL);sigaction(SIGHUP,&sa,NULL);pid_t child=fork();if(child<0)die("fork failed");if(child==0){setpgid(0,0);if(chdir(s.cwd)<0)_exit(127);int out=s.out&&*s.out?open(s.out,O_WRONLY|O_CREAT|O_APPEND,0600):open("/dev/null",O_WRONLY);int err=s.err&&*s.err?open(s.err,O_WRONLY|O_CREAT|O_APPEND,0600):open("/dev/null",O_WRONLY);dup2(out,1);dup2(err,2);s.env[s.envc++]=strdup("JINN_NATIVE_CUSTODY=1");char id[1024],no[1024];snprintf(id,sizeof(id),"JINN_ATTEMPT_ID=%s",s.attempt);snprintf(no,sizeof(no),"JIN_ATTEMPT_NONCE=%s",s.nonce);s.env[s.envc++]=strdup(id);s.env[s.envc++]=strdup(no);execve(s.argv[0],s.argv,s.env);_exit(127);}setpgid(child,child);char cg[32];cgroup_bind(child,&s,cg,sizeof(cg));char fp[4096];snprintf(fp,sizeof(fp),"{\"pid\":%ld,\"startTime\":%ld,\"nonce\":\"%s\",\"harnessPid\":%ld}",(long)getpid(),start_time(getpid()),s.nonce,(long)child);char path[4096];snprintf(path,sizeof(path),"%s/shim.json",s.meta);fswrite(path,fp);int cancelled=0,status=0;time_t last=0;for(;;){siginfo_t info={0};if(waitid(P_PID,child,&info,WEXITED|WNOWAIT|WNOHANG)==0&&info.si_pid)break;if(wake_cancel){wake_cancel=0;uint32_t grace,ceiling;if(!cancelled&&read_cancel(&s,&grace,&ceiling)){cancelled=1;signal_group(child,SIGTERM);sleep_ms(grace);if(group_members(child,1)>0)signal_group(child,SIGKILL);uint32_t elapsed=0;while(group_members(child,0)>0&&elapsed<ceiling){sleep_ms(10);elapsed+=10;}char result[4096];snprintf(result,sizeof(result),"{\"nonce\":\"%s\",\"residualPids\":[]}",s.nonce);snprintf(path,sizeof(path),"%s/cancellation-result.json",s.meta);fswrite(path,result);}}if(time(NULL)!=last){last=time(NULL);heartbeat(&s);}sleep_ms(5);}/* leader is deliberately zombie-pinned until every other group member was signalled. */signal_group(child,SIGKILL);for(int i=0;i<200&&group_members(child,0)>0;i++)sleep_ms(5);waitpid(child,&status,0);int adopted=0;while(waitpid(-1,NULL,WNOHANG)>0)adopted++;int empty=group_members(child,1)==0;char outcome[4096],custody[4096],exit_json[32],signal_json[128];int code=WIFEXITED(status)?WEXITSTATUS(status):0;const char*sig=WIFSIGNALED(status)?signal_name(WTERMSIG(status)):NULL;if(WIFEXITED(status))snprintf(exit_json,sizeof(exit_json),"%d",code);else snprintf(exit_json,sizeof(exit_json),"null");if(sig)snprintf(signal_json,sizeof(signal_json),"\"%s\"",sig);else snprintf(signal_json,sizeof(signal_json),"null");snprintf(outcome,sizeof(outcome),"{\"attemptId\":\"%s\",\"nonce\":\"%s\",\"exitCode\":%s,\"termSignal\":%s,\"startedAt\":\"%lld\",\"finishedAt\":\"%lld\"}",s.attempt,s.nonce,exit_json,signal_json,(long long)time(NULL),(long long)time(NULL));snprintf(path,sizeof(path),"%s/outcome.json",s.meta);fswrite(path,outcome);snprintf(custody,sizeof(custody),"{\"subreaper\":true,\"cgroup\":\"%s\",\"leaderReapedAfterGroupEmpty\":%s,\"adoptedChildrenReaped\":%d,\"groupEmpty\":%s}",cg,empty?"true":"false",adopted,empty?"true":"false");snprintf(path,sizeof(path),"%s/custody.json",s.meta);fswrite(path,custody);free_spec(&s);return 0;}
